def edge(
    source_id: str,
    target_id: str,
    relationship_type: str,
    source_refs: list[dict],
    notes: str = "",
    confidence: str = "high",
) -> dict:
    return {
        "id": f"{source_id}__{relationship_type}__{target_id}",
        "source_id": source_id,
        "target_id": target_id,
        "relationship_type": relationship_type,
        "source_refs": source_refs,
        "notes": notes,
        "confidence": confidence,
    }


